    (5, 'tricky-strings', 'nfc-nfd', 'viet', 'Viet with the marks as separate code points', 'Việt', 'equal to the previous row after NFC normalisation', 4, 6),
    (6, 'tricky-strings', 'ligature', 'office', 'Office typed with the fi ligature', 'ofﬁce', 'equal to plain office only after NFKC', 5, 5),
    (7, 'tricky-strings', 'ligature', 'office', 'Office typed in plain letters', 'office', 'the form the ligature row folds to', 6, 6),
    (8, 'tricky-strings', 'width', 'hello', 'Latin letters in fullwidth forms', 'ｈｅｌｌｏ', 'equal to plain hello only after NFKC', 5, 5),
    (9, 'tricky-strings', 'width', 'hello', 'Plain Latin letters', 'hello', 'the form the fullwidth row folds to', 5, 5),
