    (11, 'tricky-strings', 'case', 'none', 'Turkish dotless i', 'ısparta', 'upper-cases to I in Turkish and in most others', 7, 7),
    (12, 'tricky-strings', 'case', 'strasse', 'German sharp s', 'Straße', 'case-folds to match STRASSE', 6, 6),
    (13, 'tricky-strings', 'case', 'strasse', 'The same word in capitals', 'STRASSE', 'case-folds to match the previous row', 7, 7),
    (14, 'tricky-strings', 'case', 'none', 'Greek capitals ending in sigma', 'ΟΔΟΣ', 'lower-case ends in a final sigma, not an ordinary one', 4, 4),
    (15, 'tricky-strings', 'whitespace', 'none', 'A single space', ' ', 'treat as empty after trimming', 1, 1),
    (16, 'tricky-strings', 'whitespace', 'none', 'Three spaces', '   ', 'treat as empty after trimming', 3, 3),
    (17, 'tricky-strings', 'whitespace', 'none', 'Padded with spaces on both sides', '  padded  ', 'trim before comparing, keep for display', 10, 10),
    (18, 'tricky-strings', 'whitespace', 'none', 'No-break space between two words', 'New York', 'not split on the ordinary space', 8, 8),
    (19, 'tricky-strings', 'whitespace', 'none', 'Ideographic space alone', '　', 'trim does not remove it unless told to', 1, 1),
    (20, 'tricky-strings', 'whitespace', 'none', 'Zero-width space inside a word', 'zero​width', 'looks like one word, is two tokens to a search', 10, 10),
    (21, 'tricky-strings', 'whitespace', 'none', 'Zero-width joiner on its own', '‍', 'invisible, not empty', 1, 1),
    (22, 'tricky-strings', 'whitespace', 'none', 'Byte order mark before the text', '﻿Header', 'strip at the start of an imported file', 7, 7),
    (23, 'tricky-strings', 'numeric-like', 'none', 'Leading zeros', '007', 'keep as text, not the number 7', 3, 3),
    (24, 'tricky-strings', 'numeric-like', 'none', 'Exponent notation', '1e5', 'keep as text, not 100000', 3, 3),
